-- A 4-bit counter. Two rules write `count`; the schedule orders them.
xblue module mkCounter;
  input Bool reset;
  input Bool enable;
  Reg#(Bit#(4)) count <- mkReg(0);

  Bool full = count == 15;
  method Bit#(4) io_count = count;
  method Bool    io_full  = full;

  -- fires when its guard holds: enabled and not yet full
  rule tick (enable && !full);
    count <= count + 1;
  endrule

  rule clear (reset);
    count <= 0;
  endrule

  -- `≫` chains: clear sees tick's write and overrides it, so reset wins
  schedule tick ≫ clear;
endmodule

-- ---------------------------------------------------------------- reasoning
open XBlue

/-- The count after one clock cycle of the design itself. -/
def next (reset enable : BitVec 1) (c : BitVec 4) : BitVec 4 :=
  (mkCounter.design.cycle (.cons reset (.cons enable .nil)) (.cons c .nil)).regs.get mkCounter.count

/-- The same cycle told in schedule order: first `tick`, then `clear`. -/
def spec (reset enable : BitVec 1) (c : BitVec 4) : BitVec 4 :=
  let afterTick  := if enable = 1#1 ∧ c ≠ 15#4 then c + 1#4 else c
  let afterClear := if reset = 1#1 then 0#4 else afterTick
  afterClear

/-- The design does exactly what the story says, for every input and count. -/
theorem next_eq_spec (reset enable : BitVec 1) (c : BitVec 4) :
    next reset enable c = spec reset enable c := by
  revert reset enable c; decide

/-- Consequences, each read straight off the story. -/
theorem reset_wins (enable : BitVec 1) (c : BitVec 4) : next 1#1 enable c = 0#4 := by
  rw [next_eq_spec]; simp [spec]

theorem idle_holds (c : BitVec 4) : next 0#1 0#1 c = c := by
  rw [next_eq_spec]; simp [spec]

